<?php require_once 'app.php';require_login();$s=db()->prepare("SELECT tipo,SUM(valor) total FROM transacoes WHERE usuario_id=? GROUP BY tipo");$s->execute([user()['id']]);$v=['receita'=>0,'despesa'=>0];foreach($s as $r)$v[$r['tipo']]=(float)$r['total'];layout_start('Relatório financeiro');?><div class="row g-3"><div class="col-md-4"><div class="card p-4"><small>Receitas</small><strong class="text-success fs-4"><?=money($v['receita'])?></strong></div></div><div class="col-md-4"><div class="card p-4"><small>Despesas</small><strong class="text-danger fs-4"><?=money($v['despesa'])?></strong></div></div><div class="col-md-4"><div class="card p-4"><small>Resultado</small><strong class="fs-4"><?=money($v['receita']-$v['despesa'])?></strong></div></div></div><div class="card p-4 mt-4"><h2 class="h5">Dicas</h2><p>Use categorias consistentes para acompanhar seus hábitos e revise este relatório mensalmente.</p><a class="btn btn-outline-primary" href="gerar_pdf.php">Imprimir / exportar</a></div><?php layout_end();